def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return:
    """
    # Ensure the input is a datetime.timedelta; otherwise raise a descriptive error.
    if value is None:
        return None
    if not hasattr(value, 'total_seconds'):
        raise TypeError(f"value must be a datetime.timedelta, got {type(value).__name__}")
    try:
        # Convert to an integer number of seconds for serialization.
        return int(value.total_seconds())
    except (OverflowError, ValueError):
        # In case the conversion fails (e.g., excessively large timedelta), return None.
        return None<|return|>

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return: dict
    """
    if value is None:
        return None
    try:
        # Ensure the object has the expected attributes
        if not all(hasattr(value, attr) for attr in ("lat", "lon", "time")):
            raise TypeError("Provided object does not have required Point attributes")
        # Construct the dehydrated representation
        result = {
            "lat": getattr(value, "lat"),
            "lon": getattr(value, "lon"),
            "time": None,
        }
        time_val = getattr(value, "time")
        if time_val is None:
            result["time"] = None
        elif isinstance(time_val, str):
            # Assume it's already in ISO format
            result["time"] = time_val
        else:
            # Try to convert datetime-like objects to ISO format
            # Use the isoformat method if available
            if hasattr(time_val, "isoformat") and callable(time_val.isoformat):
                result["time"] = time_val.isoformat()
            else:
                raise ValueError("time attribute cannot be converted to ISO format")
        return result
    except Exception as exc:
        raise ValueError(f"Failed to dehydrate Point: {exc}") from exc<|return|>

def keys(self):
    """
    Return the keys of the record.

    :return: list of key names
    """
    try:
        # Attempt to fetch the internal record dictionary.
        record = getattr(self, "_record", None)
        if record is None:
            # Fallback to a generic attribute that may hold the record.
            record = getattr(self, "data", None)
        if isinstance(record, dict):
            return list(record.keys())
    except Exception:
        # In case of any unexpected issue, fall back gracefully.
        pass
    return []<|return|>

def index(self, key):
    """
    Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    # Prefer a dedicated index list if present; otherwise fall back to the data list.
    if hasattr(self, "_index") and isinstance(self._index, (list, tuple)):
        container = self._index
    elif hasattr(self, "_data") and isinstance(self._data, (list, tuple)):
        container = self._data
    else:
        raise AttributeError("object has no accessible index or data list")
    try:
        return container.index(key)
    except ValueError:
        # Item not found; mimic dictionary semantics by raising KeyError
        raise KeyError(key) from None
    except Exception as exc:
        # Any other unexpected exception is re-raised to surface debugging info
        raise type(exc)(f"Error finding index for key {key!r}") from exc<|return|>

def values(self, *keys):
        """ Return the values of the record, optionally filtering to
        include only certain values by index or key.

        :param keys: indexes or keys of the items to include; if none
                     are provided, all values will be included
        :return: list of values
        :rtype: list
        """
        try:
            # If no specific keys are requested, include all values.
            if not keys:
                # Prefer the built‑in values() method if available.
                if hasattr(self, "values"):
                    return list(self.values())
                # Fallback to iterating through items if values() is not defined.
                return [value for _, value in self.iteritems()]

            results = []
            for key in keys:
                # Handle integer indices for sequence‑like objects.
                if isinstance(key, int):
                    if hasattr(self, "__getitem__"):
                        # Use indexing if possible.
                        try:
                            results.append(self[key])
                        except IndexError as exc:
                            raise IndexError(f"Index {key} out of range for object of type {type(self).__name__}") from exc
                    else:
                        raise TypeError(f"Object of type {type(self).__name__} does not support indexing for key {key!r}")
                # Handle hashable keys for mapping‑like objects.
                elif isinstance(key, (str, bytes, int, float, frozenset)):
                    if hasattr(self, "__getitem__") and key in self:
                        try:
                            results.append(self[key])
                        except Exception as exc:
                            raise KeyError(f"Cannot retrieve value for key {key!r}") from exc
                    else:
                        raise KeyError(f"Key {key!r} not found in object of type {type(self).__name__}")
                else:
                    raise TypeError(f"Unsupported key type {type(key).__name__} for key {key!r}")

            return results
        except Exception as exc:
            raise exc
<|return|>

def data(self, *keys):
    """
    Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of None; indexes provided that are out of
    bounds will trigger an IndexError.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: IndexError if an out-of-bounds index is specified
    """
    # Ensure expected attributes exist
    if not hasattr(self, "_items"):
        raise AttributeError("Record object has no '_items' attribute")
    if not hasattr(self, "_keys"):
        raise AttributeError("Record object has no '_keys' attribute")

    items = self._items
    # _keys should be a list of field names in order; if a dict is supplied,
    # use its keys in insertion order.
    if isinstance(self._keys, dict):
        key_order = list(self._keys.keys())
    else:
        key_order = list(self._keys)

    # Helper to get value by key name, with None for missing keys
    def _get_by_name(name):
        if name in key_order:
            idx = key_order.index(name)
            return items[idx]
        return None

    # If no keys supplied, return all items
    if not keys:
        return {name: value for name, value in zip(key_order, items)}

    result = {}
    for k in keys:
        if isinstance(k, int):
            idx = k
            if idx < 0 or idx >= len(items):
                raise IndexError(f"Index {idx} is out of bounds.")
            key_name = key_order[idx]
            result[key_name] = items[idx]
        else:
            # Treat as a key name; if not present, None
            result[k] = _get_by_name(k)
    return result<|return|>

def pop_u16(self):
    """ Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    try:
        if not hasattr(self, 'data'):
            raise AttributeError("Attribute 'data' is missing.")
        if not isinstance(self.data, (bytes, bytearray)):
            raise TypeError("Attribute 'data' must be bytes or bytearray.")
        if len(self.data) < 2:
            raise ValueError("Not enough data to pop 2 bytes.")
        last_two = self.data[-2:]
        if isinstance(self.data, bytearray):
            del self.data[-2:]
        else:
            self.data = self.data[:-2]
        return int.from_bytes(last_two, byteorder='big', signed=False)
    except Exception as exc:
        raise RuntimeError(f"Failed to pop u16: {exc}") from exc<|return|>

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    if not isinstance(message, str):
        raise TypeError("message must be a string")

    def decorator(func):
        if not callable(func):
            raise TypeError("decorated object must be callable")

        # Append deprecation notice to docstring, if any
        existing_doc = func.__doc__ or ""
        deprecation_note = f"\n\nDeprecated: {message}"
        new_doc = existing_doc + deprecation_note

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, category=DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)

        wrapper.__doc__ = new_doc
        return wrapper

    return decorator<|return|>

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
            return _update_wrapper(wrapper, func)

        if lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except Exception:
                    pass  # value could not be stored
                return v
            return _update_wrapper(wrapper, func)

        def wrapper(*args, **kwargs):
            k = key(*args, **kwargs)
            try:
                with lock:
                    return cache[k]
            except KeyError:
                pass  # key not found
            v = func(*args, **kwargs)
            try:
                with lock:
                    cache[k] = v
            except Exception:
                pass  # value could not be stored
            return v
        return _update_wrapper(wrapper, func)

    return decorator<|return|>

def setdefault(self, key, default=None):
    """D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D"""
    # Ensure the underlying storage dictionary exists
    if not hasattr(self, "storage") or not isinstance(self.storage, dict):
        raise AttributeError("Object must have a 'storage' attribute of type dict")

    try:
        # Attempt to retrieve the existing value
        return self.storage[key]
    except KeyError:
        # Key is missing, set the default value
        self.storage[key] = default
        return default
    except TypeError:
        # Key is not hashable
        raise TypeError("setdefault: key must be hashable")<|return|>

def get(self, key, default=None):
        """D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None."""
        try:
            return self[key]
        except KeyError:
            return default<|return|>

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """
    def decorator(method):
        if lock is None:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
                    return c[k]
                except KeyError:
                    pass  # key not found
                v = method(self, *args, **kwargs)
                try:
                    c[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
                    with lock(self):
                        return c[k]
                except KeyError:
                    pass  # key not found
                v = method(self, *args, **kwargs)
                try:
                    with lock(self):
                        c[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, method)
    return decorator<|return|>

def is_file_exist(file_name):
    """
    Check if file name exist.
    :param file_name: File name.
    :type file_name: str
    :return: Return true (exist), false (do not exist, or invalid file name)
    :rtype bool
