@classmethod
def _reset_logging(cls):
    """Reset"""
    try:
        root_logger = logging.getLogger()
        # Remove all handlers from the root logger
        for handler in root_logger.handlers[:]:
            handler.close()
            root_logger.removeHandler(handler)
        # Reset root logger level and propagate flag
        root_logger.setLevel(logging.NOTSET)
        root_logger.propagate = True

        # Also clear handlers and reset levels on all named loggers
        for logger_name, logger_obj in logging.Logger.manager.loggerDict.items():
            # Skip placeholders
            if isinstance(logger_obj, logging.PlaceHolder):
                continue
            for handler in logger_obj.handlers[:]:
                handler.close()
                logger_obj.removeHandler(handler)
            logger_obj.setLevel(logging.NOTSET)
    except Exception as exc:
        # Log the exception on the root logger and re-raise
        logging.getLogger().error("Failed to reset logging: %s", exc)
        raise<|return|>

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    result = []
    for cls in classes:
        if not isinstance(cls, type):
            raise TypeError("elements of classes must be types")
        # Skip if already covered by an existing base
        if any(issubclass(cls, existing) for existing in result):
            continue
        # Remove bases that are subclasses of the current class
        result = [existing for existing in result if not issubclass(existing, cls)]
        result.append(cls)
    return result<|return|>

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    if not isinstance(all, bool):
        raise TypeError("Parameter 'all' must be a boolean.")
    try:
        # Own class attributes (excluding special/private ones)
        own_attrs = [name for name, value in vars(self.__class__).items()
                     if not name.startswith("_")]
        if all:
            # Include attributes from base classes as well
            attrs = []
            for cls in self.__class__.__mro__:
                if cls is object:
                    continue
                attrs.extend(
                    [name for name, value in vars(cls).items()
                     if not name.startswith("_")]
                )
            # Remove duplicates while preserving order
            seen = set()
            unique_attrs = []
            for name in attrs:
                if name not in seen:
                    seen.add(name)
                    unique_attrs.append(name)
            return unique_attrs
        return own_attrs
    except Exception as exc:
        raise RuntimeError("Failed to retrieve interface attribute names.") from exc<|return|>

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    if Broken in getattr(sequence, "__bases__", ()):
        output.append(sequence)
    else:
        cls = sequence.__class__
        if InterfaceClass in cls.__mro__ or zope.interface.declarations.Implements in cls.__mro__:
            output.append(sequence)
        else:
            for v in sequence:
                _normalizeargs(v, output)
    return output<|return|>

def _c_optimizations_available():
    """
    Return the C optimization module, if available, otherwise
    a false value.

    If the optimizations are required but not available, this
    raises the ImportError.

    This does not say whether they should be used or not.
    """
    import importlib.util
    try:
        spec = importlib.util.find_spec("c_optimizations")
        if spec is not None:
            # Module is available; import and return it
            return importlib.util.module_from_spec(spec)
        else:
            return False
    except ImportError as exc:
        # Module is required but not present, re‑raise the error
        raise ImportError("C optimizations required but not available") from exc
    except Exception:
        # Any other exception is treated as module not found
        return False<|return|>

import os, sys

def _should_attempt_c_optimizations():
    """Return a true value if we should attempt to use the C optimizations.

    This takes into account whether we're on PyPy and the value of the
    ``PURE_PYTHON`` environment variable, as defined in `_use_c_impl`.
    """
    # Check environment variable for pure Python flag
    try:
        pure_py = os.getenv('PURE_PYTHON', '').lower()
        if pure_py in {'1', 'true', 'yes'}:
            return False
    except Exception:
        # If we cannot read the environment variable, assume defaults
        pass

    # Check for PyPy implementation
    try:
        if getattr(sys, 'implementation', None) and sys.implementation.name.lower() == 'pypy':
            return False
    except Exception:
        # Fallback: look for sys.pypy_version_info which exists on PyPy
        try:
            if hasattr(sys, 'pypy_version_info'):
                return False
        except Exception:
            pass

    return True<|return|>

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset context to an empty dict
    self.context = {}

    # Determine how to reinitialize bins
    try:
        if hasattr(self, "initial_value") and self.initial_value is not None:
            # Reinitialize existing bins to the initial value
            if hasattr(self, "counts_len"):
                bin_count = self.counts_len
            else:
                bin_count = len(self.counts) if hasattr(self, "counts") else 0
            self.counts = [self.initial_value] * bin_count
        else:
            # Use make_bins to create a fresh set of bins
            self.counts = self.make_bins()
    except Exception as e:
        # If any error occurs during reset, clear counts to an empty list to avoid stale state
        self.counts = []
        raise RuntimeError(f"Failed to reset histogram bins: {e}") from e<|return|>

def to_csv(self, separator=",", header=None):
    """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
          Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    lines = []

    # Add header if provided.
    if header is not None:
        lines.append(str(header))

    sep = str(separator)

    # Iterate over graph points. Expect each point to be a (coordinate, value)
    # tuple, but allow other formats.
    for point in self:
        try:
            if isinstance(point, tuple) and len(point) == 2:
                coord, value = point
            else:
                # Fall back: treat point as coordinate, no value.
                coord, value = point, None
        except Exception:
            # Skip points that can't be unpacked.
            continue

        # Build list of CSV parts.
        parts = []

        # Handle coordinate: treat non-string iterables specially.
        try:
            if isinstance(coord, (str, bytes)):
                coord_items = [coord]
            else:
                coord_items = list(coord)
        except Exception:
            coord_items = [coord]

        for c in coord_items:
            parts.append(str(c))

        # Handle value: if scalar or string, add directly; otherwise
        # iterate over its elements.
        if value is not None:
            try:
                if isinstance(value, (str, bytes)):
                    parts.append(str(value))
                else:
                    for val in value:
                        parts.append(str(val))
            except Exception:
                # If value can't be iterated, treat as scalar.
                parts.append(str(value))

        # Join parts using the separator and append to output.
        lines.append(sep.join(parts))

    return "\n".join(lines)<|return|>

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    if not isinstance(coord_name, str):
        raise TypeError("coord_name must be a string")
    # First check if the coordinate is a variable owned by this object
    if hasattr(self, "_variables") and isinstance(self._variables, dict):
        if coord_name in self._variables:
            var = self._variables[coord_name]
            # Prefer an explicit `error_indices` attribute if it exists
            if hasattr(var, "error_indices"):
                return np.asarray(var.error_indices, dtype=int)
            # Some implementations store errors in an `errors` attribute
            if hasattr(var, "errors"):
                return np.asarray(var.errors, dtype=int)
    # Fallback to a generic mapping on the instance
    if hasattr(self, "err_indices") and isinstance(self.err_indices, dict):
        if coord_name in self.err_indices:
            return np.asarray(self.err_indices[coord_name], dtype=int)
    # If nothing is found, raise an informative error
    raise KeyError(f"No error indices found for coordinate '{coord_name}'.")<|return|>

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Convert inputs to numpy arrays
    try:
        bins = np.asarray(bins, dtype=float)
    except Exception as exc:
        raise ValueError("bins must be array-like and convertible to float") from exc

    # edges may be a 1-D array or a list/tuple of arrays
    if isinstance(edges, (list, tuple)):
        edges_list = list(edges)
    else:
        edges_list = [np.asarray(edges, dtype=float)]

    # Validate dimensions
    ndim = bins.ndim
    if len(edges_list) != ndim:
        raise ValueError(f"Number of edge arrays ({len(edges_list)}) does not match "
                         f"bins dimensions ({ndim}).")

    # Compute width arrays for each axis
    widths = []
    for i, edge in enumerate(edges_list):
        edge = np.asarray(edge, dtype=float)
        if edge.ndim != 1:
            raise ValueError(f"edge array at index {i} must be 1-D.")
        if edge.size < 2:
            raise ValueError(f"edge array at index {i} must contain at least two points.")
        widths.append(np.diff(edge))

    # Broadcast widths to match bins shape
    volume = np.ones(bins.shape, dtype=float)
    for i, w in enumerate(widths):
        shape = [1] * ndim
        shape[i] = -1
        try:
            volume *= np.reshape(w, shape)
        except Exception as exc:
            raise ValueError(f"Could not broadcast width of axis {i} with shape {w.shape} "
                             f"to bins shape {bins.shape}.") from exc

    # Compute integral
    try:
        total = np.sum(bins * volume)
    except Exception as exc:
        raise RuntimeError("Failed to compute integral due to array shape mismatch.") from exc

    return float(total)<|return|>

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    try:
        # If the sequence itself is a single FillRequest instance, it's valid.
        if isinstance(seq, FillRequest):
            return True
        # A sequence of Source objects is explicitly forbidden.
        if isinstance(seq, Source):
            return False
        # Strings and bytes should not be treated as iterables of requests.
        if isinstance(seq, (str, bytes)):
            return False
        # Obtain an iterator: for dicts, iterate over values; otherwise use seq directly.
        iterator = seq.values() if isinstance(seq, dict) else seq
        for item in iterator:
            if isinstance(item, FillRequest):
                return True
        return False
    except Exception:
        # If seq is not iterable or any other error occurs, it's not a valid FillRequestSeq.
        return False<|return|>

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    try:
        return (
            obj is not None
            and hasattr(obj, "fill") and callable(getattr(obj, "fill", None))
            and hasattr(obj, "request") and callable(getattr(obj, "request", None))
        )
    except Exception:
        return False<|return|>

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    try:
        return callable(getattr(obj, "fill", None)) and callable(getattr(obj, "compute", None))
    except Exception:
        return False<|return|>

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    def _diff(a, b, lvl):
        diff = {}
        for k, va in a.items():
            if k not in b:
                # key missing in b: copy entire subtree
                if isinstance(va, dict):
                    diff[k] = _diff(va, {}, lvl if lvl < 0 else lvl - 1)
                else:
                    diff[k] = va
            else:
                vb = b[k]
                if isinstance(va, dict) and isinstance(vb, dict):
                    if lvl == 0:
                        if va != vb:
                            diff[k] = va
                    else:
                        sub = _diff(va, vb, lvl if lvl < 0 else lvl - 1)
                        if sub:
                            diff[k] = sub
                else:
                    if va != vb:
                        diff[k] = va
        return diff

    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("both arguments must be dictionaries")
    return _diff(d1, d2, level)<|return|>

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    import numpy as np  # lazy import to avoid assuming global import
    # Convert coord to array
    try:
        coord_arr = np.asarray(coord, dtype=float)
    except Exception as exc:
        raise TypeError("coord must be array-like and convertible to float") from exc

    # Handle 1-dim histogram
    if isinstance(self.edges, np.ndarray) and self.edges.ndim == 1:
        edge = self.edges
        if coord_arr.ndim != 0 and coord_arr.size != 1:
            raise ValueError("For 1‑D histogram, coord must be a scalar.")
        try:
            idx = np.searchsorted(edge, float(coord_arr), side="right") - 1
        except Exception:
            return  # invalid coordinate, ignore
        if 0 <= idx < edge.size - 1:
            try:
                self.hist[idx] += weight
            except Exception:
                raise
        # outside edges => ignore
        return

    # Handle multi‑dimensional histogram
    if not isinstance(self.edges, (list, tuple)):
        raise TypeError("self.edges must be a list or tuple of arrays for multi‑D histograms")
    ndim = len(self.edges)
    if coord_arr.size != ndim:
        raise ValueError(f"coord must have {ndim} components, got {coord_arr.size}")
    indices = []
    for dim, edge in enumerate(self.edges):
        try:
            idx = np.searchsorted(edge, float(coord_arr[dim]), side="right") - 1
        except Exception:
            return  # invalid coordinate, ignore
        if 0 <= idx < edge.size - 1:
            indices.append(idx)
        else:
            return  # coordinate outside the histogram bounds
    try:
        self.hist[tuple(indices)] += weight
    except Exception as exc:
        raise RuntimeError("Failed to update histogram bin") from exc
    return
<|return|>

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re
    from django.core.exceptions import ValidationError

    key_regex = re.compile(r'^[A-Za-z][A-Za-z0-9_-]*$')
    value_regex = re.compile(r'^[A-Za-z0-9_-]*$')

    errors = []

    def _append_err(key_repr, msg):
        errors.append({key_repr: msg})

    for key, value in labels.items():
        # validate key type
        if not isinstance(key, (str, bytes)):
            _append_err(str(key), "expected string or bytes-like object")
        else:
            # validate key regex
            try:
                if not key_regex.match(key):
                    _append_err(key, f"Label key '{key}' does not match the regex [{key_regex.pattern}]")
            except Exception:
                _append_err(key, "expected string or bytes-like object")

        # helper to validate a single label value
        def _check_value(val):
            # value type
            if not isinstance(val, (str, bytes)):
                _append_err(str(val), "expected string or bytes-like object")
                return
            # value regex
            try:
                if not value_regex.match(val):
                    _append_err(val, f"Label value '{val}' does not match the regex [{value_regex.pattern}]")
            except Exception:
                _append_err(val, "expected string or bytes-like object")

        # validate value(s)
        if isinstance(value, (list, tuple)):
            for element in value:
                _check_value(element)
        else:
            _check_value(value)

    if errors:
        raise ValidationError(errors)<|return|>

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.

    """
    def _transform(node, is_first):
        if isinstance(node, dict):
            transformed = {}
            for key, value in node.items():
                if isinstance(value, (dict, list)):
                    transformed[key] = _transform(value, False)
                else:
                    # On the first level keep all non-dict/non-list values,
                    # otherwise replace with None
                    transformed[key] = value if is_first else None
            return transformed
        elif isinstance(node, list):
            # Lists are not first level; each element is transformed with is_first=False
            return [_transform(item, False) for item in node]
        else:
            # Primitive values: replace with None unless first level
            return node if is_first else None

    if manifest_dict is None:
        return {}
    if not isinstance(manifest_dict, dict):
        raise TypeError(f"Expected dict, got {type(manifest_dict).__name__}")
    return _transform(manifest_dict, first_level)<|return|>

