def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Basic validation
    if not hasattr(app, "spec"):
        raise AttributeError("Application object must have a 'spec' attribute")
    spec = app.spec

    if not hasattr(spec, "manifest"):
        raise AttributeError("Spec must contain a 'manifest' attribute")
    manifest = spec.manifest

    if not isinstance(manifest, (list, tuple)):
        raise TypeError("spec.manifest should be a list or tuple of resources")

    # Retrieve existing observer schemas, if any
    observer_schemas = getattr(app, "observer_schema", None)
    if observer_schemas is None:
        observer_schemas = getattr(app, "observer_schemas", None)
    if observer_schemas is None:
        observer_schemas = {}
    if not isinstance(observer_schemas, dict):
        raise TypeError("observer_schema(s) attribute must be a dict if it exists")

    # Generate defaults for resources missing schemas
    for resource in manifest:
        if not isinstance(resource, dict):
            continue

        kind = resource.get("kind")
        if not kind:
            continue

        # Skip if a schema is already specified
        if kind in observer_schemas:
            continue

        api_version = resource.get("apiVersion", "v1")
        metadata = resource.get("metadata", {})
        name = metadata.get("name", f"default-{kind.lower()}")

        default_schema = {
            "apiVersion": api_version,
            "kind": kind,
            "metadata": {"name": name},
        }

        observer_schemas[kind] = default_schema

    # Store back to the application object
    try:
        setattr(app, "observer_schema", observer_schemas)
    except Exception:
        try:
            setattr(app, "observer_schemas", observer_schemas)
        except Exception as e:
            raise RuntimeError("Failed to set observer schema on application") from e

    return observer_schemas<|return|>

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    try:
        # Ensure prefix is a string
        if not isinstance(prefix, str):
            prefix = str(prefix)

        # Attempt to locate a log-like attribute in the instance
        logs_attr_names = ('log', 'messages', 'validation_log')
        logs = None
        for name in logs_attr_names:
            if hasattr(self, name):
                logs = getattr(self, name)
                break

        # If no explicit log attribute, search for any iterable that looks like a log
        if logs is None:
            for attr in vars(self).values():
                if isinstance(attr, (list, tuple)):
                    logs = attr
                    break

        # Default to an empty list if still not found
        if logs is None:
            logs = []

        # Convert the log items into string lines with the prefix
        if isinstance(logs, (list, tuple)):
            return "\n".join(f"{prefix}{item}" for item in logs)
        else:
            # Single object case
            return f"{prefix}{str(logs)}"
    except Exception as exc:
        # Fallback string if something goes wrong
        return f"{prefix}ERROR generating status string: {exc}"<|return|>

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")

    # Default to the instance's spec version
    spec_version = self.spec_version

    if extract_spec_version:
        type_value = inventory.get("type")
        if isinstance(type_value, str):
            # Expect something like "NFDI4Chem-Inventory-1.0"
            parts = type_value.rsplit("-", 1)
            if len(parts) == 2 and all(c.isdigit() or c == "." for c in parts[1]):
                try:
                    # Verify the version string can be interpreted as a float
                    float(parts[1])
                    spec_version = parts[1]
                except ValueError:
                    # keep default if parsing fails
                    pass

    # Use a helper method that performs the actual logic against the chosen spec
    try:
        self._validate_inventory(inventory, spec_version)
    except Exception as exc:
        # Re‑raise as a generic ValidationError if one exists;
        # otherwise, preserve the original exception context.
        raise RuntimeError(f"Inventory validation failed: {exc}") from exc

    return True<|return|>

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Validate inputs
    if not isinstance(manifest_files, dict):
        raise TypeError("manifest_files must be a dict mapping filenames to digests")
    if not isinstance(digests_used, (set, list)):
        raise TypeError("digests_used must be a set or list of digest strings")

    digests_used = set(digests_used)

    # Collect missing digests
    missing = []
    for filename, digest in manifest_files.items():
        if digest is None or digest == "":
            continue
        if digest not in digests_used:
            missing.append((filename, digest))

    if missing:
        msg_parts = [f"{digest} (file '{fname}')" for fname, digest in missing]
        raise ValueError(f"Required digests not used: {', '.join(msg_parts)}")

    # Collect digests that were used but not declared in the manifest
    declared_digests = set(filter(None, manifest_files.values()))
    unused = digests_used - declared_digests
    if unused:
        raise ValueError(f"Digests used but not declared in manifest: {', '.join(unused)}")

    return True<|return|>

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: ``logical_path_in_state`` -> ``set(content_files)``.

    The set of ``content_files`` may include references to duplicate files in
    later versions than the version being described.
    """
    if version is None:
        raise ValueError("`version` must not be None")

    logical_map = {}

    # Inventory might be a mapping from logical_path -> (dict or list)
    if isinstance(inventory, dict):
        for logical_path, data in inventory.items():
            try:
                # If the value itself is a mapping of version -> set/list of files
                if isinstance(data, dict):
                    files = data.get(version)
                    if files:
                        logical_map[logical_path] = set(files)
                    continue

                # If the value is a list/tuple of records with 'version' and
                # 'content_file' keys
                if isinstance(data, (list, tuple)):
                    files = [rec.get("content_file")
                             for rec in data
                             if rec.get("version") == version]
                    if files:
                        logical_map[logical_path] = set(files)
                    continue
            except Exception as exc:
                raise RuntimeError(
                    f"Failed to process logical path '{logical_path}': {exc}"
                ) from exc

    # Inventory might be an iterable of record dicts
    elif hasattr(inventory, "__iter__"):
        for rec in inventory:
            try:
                rec_logic = rec["logical_path"]
                rec_version = rec["version"]
                rec_file = rec["content_file"]
                if rec_version != version:
                    continue
                logical_map.setdefault(rec_logic, set()).add(rec_file)
            except Exception as exc:
                raise RuntimeError(
                    f"Failed to process record {rec}: {exc}"
                ) from exc

    else:
        raise TypeError(f"Unsupported inventory type: {type(inventory)}")

    return logical_map<|return|>

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        # Basic type checks
        if not isinstance(fixity, dict):
            raise TypeError("fixity must be a dict, got {!r}".format(type(fixity).__name__))

        if not isinstance(manifest_files, (set, list, tuple)):
            raise TypeError("manifest_files must be a collection of file names")

        # Ensure required keys are present
        required_keys = ("files",)
        for key in required_keys:
            if key not in fixity:
                raise ValueError(f"Missing required key '{key}' in fixity block")

        files_list = fixity["files"]

        # Validate that 'files' entry is iterable of file names
        if not isinstance(files_list, (list, tuple)):
            raise TypeError("The 'files' entry must be a list or tuple, got {!r}".format(type(files_list).__name__))

        # Verify each referenced file exists in the manifest
        for file_name in files_list:
            if file_name not in manifest_files:
                raise ValueError(f"File '{file_name}' referenced in fixity block is not present in the manifest")

        # Optional: check for checksum validity if present
        if "checksum" in fixity and not isinstance(fixity["checksum"], str):
            raise TypeError("The 'checksum' entry must be a string")

        # If no exceptions, the block is considered valid
        return None<|return|>

def files_list(path):
    """
    Return the files in `path`
    """
    import os
    if not os.path.exists(path):
        raise FileNotFoundError(path)
    if os.path.isfile(path):
        return [os.path.abspath(path)]
    if os.path.isdir(path):
        files = []
        try:
            for fname in os.listdir(path):
                fpath = os.path.join(path, fname)
                if os.path.isfile(fpath):
                    files.append(os.path.abspath(fpath))
        except OSError:
            raise
        return files
    raise FileNotFoundError(path)<|return|>

