    return True<|return|>

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    result = {}
    if not isinstance(zip_path, str) or not zip_path:
        return result
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            for info in zf.infolist():
                if info.is_dir():
                    continue
                name = info.filename
                base, ext = os.path.splitext(os.path.basename(name))
                try:
                    content_bytes = zf.read(info)
                except Exception:
                    # skip unreadable file
                    continue
                if ext.lower() == '.xml':
                    try:
                        content = content_bytes.decode('utf-8', errors='ignore')
                    except Exception:
                        content = content_bytes
                    result.setdefault(base, {})['xml'] = content
                else:
                    group = result.setdefault(base, {})
                    files_dict = group.setdefault('files', {})
                    files_dict[os.path.basename(name)] = content_bytes
    except (FileNotFoundError, zipfile.BadZipFile):
        # Return empty dict if file can't be opened
        return result
    except Exception:
        # On any unexpected error, return what we have so far
        return result
    return result<|return|>

