def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    def _format(obj, level, visited):
        prefix = ' ' * (indent * level)
        if id(obj) in visited:
            return f'{prefix}<recursion>'
        visited.add(id(obj))
        if isinstance(obj, dict):
            if not obj:
                return f'{prefix}{{}}'
            lines = [f'{prefix}{{']
            for key, val in sorted(obj.items(), key=lambda x: str(x[0])):
                lines.append(f"{' ' * (indent * (level + 1))}{repr(key)}: {_format(val, level + 1, visited)}")
            lines.append(f'{prefix}}}')
            return '\n'.join(lines)
        elif isinstance(obj, (list, tuple, set)):
            if not obj:
                return f'{prefix}{type(obj).__name__}()'
            open_sym, close_sym = {'list': ('[', ']'), 'tuple': ('(', ')'), 'set': ('{', '}')}[type(obj).__name__]
            lines = [f'{prefix}{open_sym}']
            for item in obj:
                lines.append(_format(item, level + 1, visited))
            lines.append(f'{prefix}{close_sym}')
            return '\n'.join(lines)
        elif hasattr(obj, '__dict__'):
            return _format(vars(obj), level, visited)
        else:
            return f'{prefix}{repr(obj)}'

    try:
        representation = _format(self, 0, set())
        if debug:
            header = f'<{self.__class__.__name__} at {hex(id(self))}>'
            return f'{header}\n{representation}'
        return representation
    except Exception as exc:  # pragma: no cover
        return f'<Error prettying {self.__class__.__name__}: {exc}>'
<|return|>

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def is_op(expr, op):
        return (
            isinstance(expr, tuple) and
            len(expr) >= 3 and
            expr[0] == op
        )

    def simplify(expr):
        # Base case: leaf nodes are unchanged
        if not isinstance(expr, tuple):
            return expr
        op = expr[0]
        # Recursively simplify operands
        ops = [simplify(e) for e in expr[1:]]
        if op in ("and", "or"):
            if len(ops) != 2:
                # Unsupported arity; return as-is
                return (op, *ops)
            left, right = ops
            # Absorption rules
            if op == "and":
                # A & (A | B) => A
                if is_op(right, "or") and right[1] == left:
                    return right[2]
                if is_op(left, "or") and left[1] == right:
                    return left[2]
                # Negative absorption: A & (~A | B) => A & B
                if is_op(right, "or") and is_op(right[1], "not") and right[1][1] == left:
                    return ("and", left, right[2])
                if is_op(left, "or") and is_op(left[1], "not") and left[1][1] == right:
                    return ("and", right, left[2])
            elif op == "or":
                # A | (A & B) => A
                if is_op(right, "and") and right[1] == left:
                    return right[2]
                if is_op(left, "and") and left[1] == right:
                    return left[2]
                # Negative absorption: A | (~A & B) => A | B
                if is_op(right, "and") and is_op(right[1], "not") and right[1][1] == left:
                    return ("or", left, right[2])
                if is_op(left, "and") and is_op(left[1], "not") and left[1][1] == right:
                    return ("or", right, left[2])
        # Reconstruct expression after simplification
        return (op, *ops)

    if args is None:
        raise ValueError("args must be a non-empty iterable of expressions")
    result = []
    for expr in args:
        try:
            simplified = simplify(expr)
            result.append(simplified)
        except Exception as exc:
            # Preserve the original exception traceback for debugging
            raise RuntimeError(f"Failed to absorb expression {expr!r}") from exc
    return result<|return|>

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.
    """
    if hook is None:
        raise ValueError("Hook cannot be None")

    def decorator(fn):
        if not callable(fn):
            raise TypeError("Handler must be callable")

        try:
            # Ensure storage exists
            if not hasattr(self, "_handlers"):
                self._handlers = {}
            # Register handler
            self._handlers.setdefault(hook, []).append(fn)
        except Exception as exc:
            raise RuntimeError(f"Could not register handler for hook {hook}") from exc
        return fn

    return decorator<|return|>

