def get_versions():
    """Get version information or return default if unable to do so."""
    # Try reading a simple VERSION file first
    try:
        with open("VERSION", "r", encoding="utf-8") as f:
            return f.read().strip()
    except Exception:
        pass

    # Next, look for a version defined in a version.py file
    try:
        with open("version.py", "r", encoding="utf-8") as f:
            for line in f:
                stripped = line.strip()
                if stripped.startswith("VERSION"):
                    # Accept either 'VERSION = "1.2.3"' or 'VERSION = 1.2.3'
                    _, value = stripped.split("=", 1)
                    return value.strip().strip('"\'')
    except Exception:
        pass

    # If all attempts fail, return a sensible default
    return "unknown"<|return|>

def render(pieces, style):
