        if not isinstance(style, str):
            raise TypeError("style must be a string")

        if style == "plain":
            return " ".join(str(p) for p in pieces)
        if style == "lines":
            return "\n".join(str(p) for p in pieces)
        if style == "json":
            # simple JSON-style representation without importing json
            quoted = ", ".join(repr(p) for p in pieces)
            return f"[{quoted}]"

        raise ValueError(f"Unsupported style: {style}")
    except Exception:
        # In case of any error, return an empty string to avoid crashing callers
        return ""<|return|>

def plus_or_dot(pieces):
    """
    Return a + if we don't already have one, else return a .

    :param pieces: Iterable or string to search for a '+' character.
    :return: '+' or '.' depending on presence of '+' in pieces.
    """
    if pieces is None:
        raise ValueError("pieces cannot be None")
    if isinstance(pieces, str):
        has_plus = '+' in pieces
    elif isinstance(pieces, (list, tuple, set, frozenset)):
        has_plus = any(str(item) == '+' for item in pieces)
    else:
        raise TypeError(f"Unsupported type {type(pieces).__name__} for pieces")
    return '.' if has_plus else '+'<|return|>

def register_vcs_handler(vcs, method):  # type: (str, str) -> typing.Callable
    """Create decorator to mark a method as the handler of a VCS."""
    if not isinstance(vcs, str):
        raise TypeError(f"vcs must be a string, got {type(vcs).__name__}")
    if not isinstance(method, str):
        raise TypeError(f"method must be a string, got {type(method).__name__}")

    def decorate(f):
        """Store f in HANDLERS[vcs][method]."""
        try:
            HANDLERS.setdefault(vcs, {})[method] = f
        except Exception as exc:
            raise RuntimeError(
                f"Failed to register handler for vcs={vcs!r}, method={method!r}"
            ) from exc
        return f

    return decorate<|return|>

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    import hashlib

    num_objects = 0
    good_objects = 0

    def _walk(node):
        nonlocal num_objects, good_objects
        num_objects += 1

        # Validate the node itself if required
        if validate_objects:
            if hasattr(node, 'validate') and callable(node.validate):
                try:
                    node.validate()
                    good_objects += 1
                except Exception as exc:
                    if show_warnings:
                        print(f"Warning: validation failed for node {getattr(node, 'name', node)}: {exc}")
            else:
                # If there is no explicit validate method, assume node is valid
                good_objects += 1

        # Check digest if required
        if check_digests:
            if hasattr(node, 'data') and hasattr(node, 'digest'):
                try:
                    digest = hashlib.sha256(repr(node.data).encode('utf-8')).hexdigest()
                    if digest != node.digest:
                        if show_warnings:
                            print(f"Warning: digest mismatch for node {getattr(node, 'name', node)}")
                except Exception as exc:
                    if show_warnings:
                        print(f"Warning: failed to compute digest for node {getattr(node, 'name', node)}: {exc}")

        # Recurse into children if any
        children = None
        if hasattr(node, 'children'):
            children = node.children
        elif isinstance(node, dict) and 'children' in node:
            children = node['children']
        if children:
            try:
                for child in children:
                    _walk(child)
            except Exception as exc:
                if show_warnings:
                    print(f"Warning: failed to walk children of node {getattr(node, 'name', node)}: {exc}")

    # Determine the starting point(s) of the hierarchy
    root = getattr(self, 'root', None)
    if root is None:
        return 0, 0

    # Root could be a single node or a collection
    if hasattr(root, 'children') or isinstance(root, list):
        for r in root if isinstance(root, list) else root.children:
            _walk(r)
    else:
        # Treat root itself as a single node
        _walk(root)

    return num_objects, good_objects<|return|>

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    # The root path must be provided via the instance.
    try:
        root = self.root
    except AttributeError:
        raise AttributeError("Instance must define a 'root' attribute for the storage root path.")

    if not isinstance(root, (bytes, str)):
        raise TypeError("root path must be a string or bytes, got %r" % type(root))

    # Ensure root is a directory and empty.
    if os.path.exists(root):
        if not os.path.isdir(root):
            raise FileExistsError(f"{root!r} exists but is not a directory.")
        if os.listdir(root):
            raise FileExistsError(f"{root!r} already exists and is not empty.")
    else:
        try:
            os.makedirs(root, exist_ok=True)
        except OSError as exc:
            raise OSError(f"Failed to create storage root at {root!r}") from exc

    # Create minimal OCFL structure: objects directory and a sample object.
    try:
        os.makedirs(os.path.join(root, "objects", "00000001"), exist_ok=True)
        layout_path = os.path.join(root, "layout.json")
        if not os.path.exists(layout_path):
            with open(layout_path, "w", encoding="utf-8") as f:
                f.write('{"layout": "default", "version": "1.0"}')
    except OSError as exc:
        raise OSError(f"Failed to set up OCFL directory structure in {root!r}") from exc

    # Persist the root path on the instance for later use.
    self.root_path = root
    return root<|return|>

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version:
        raise ValueError("Empty version string")

    parts = version.strip().split('.')
    if not parts:
        raise ValueError("Invalid version format")

    # Find the last part that consists solely of digits
    idx = len(parts) - 1
    while idx >= 0 and not parts[idx].isdigit():
        idx -= 1

    if idx < 0:
        raise ValueError("No numeric component found to increment in '%s'" % version)

    try:
        num = int(parts[idx])
    except ValueError:
        raise ValueError("Failed to parse numeric component '%s'" % parts[idx])

    # Increment number
    new_num_str = str(num + 1)

    # Preserve original zero padding if present
    if len(parts[idx]) > len(new_num_str):
        new_num_str = new_num_str.zfill(len(parts[idx]))

    parts[idx] = new_num_str
    return '.'.join(parts)<|return|>

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        if not os.path.exists(path):
            return f'error: path "{path}" does not exist'
        if not os.path.isdir(path):
            return 'file'
        # Directory: check for Namaste files starting with "0="
        try:
            for entry in os.listdir(path):
                full_path = os.path.join(path, entry)
                if os.path.isfile(full_path) and entry.startswith('0='):
                    return 'object'
        except PermissionError:
            return f'error: permission denied accessing directory "{path}"'
        return 'root'
    except PermissionError:
        return f'error: permission denied accessing "{path}"'
    except OSError as e:
        return f'error: {e.strerror}'<|return|>

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    if parser is None:
        raise ValueError("parser cannot be None")

    # Attempt to obtain the list of actions; raise a clear error if this fails
    try:
        actions = parser._actions
    except AttributeError:
        raise TypeError("Expected an argparse.ArgumentParser instance")

    flags = []
    for action in actions:
        # Some actions, like positional arguments, may not have option_strings
        option_strings = getattr(action, 'option_strings', [])
        for opt in option_strings:
            if opt:  # ignore empty strings
                flags.append(opt)

    return ' '.join(flags)<|return|>

def parse_arguments(*arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as an ArgumentParser instance.
    '''
    parser = argparse.ArgumentParser(description='Argument parser for the script.')
    # If no explicit arguments are passed, argparse will automatically use sys.argv[1:].
    try:
        return parser.parse_args(arguments if arguments else None)
    except Exception as exc:
        # Re-raise any parsing errors with context for easier debugging
        raise ValueError("Error parsing command-line arguments") from exc<|return|>

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    try:
        flags = [opt for act in getattr(parser, "_actions", ())
                 for opt in getattr(act, "option_strings", ())
                 if opt.startswith('-')]
        return ' '.join(sorted(flags))
    except Exception:
        return ''<|return|>

def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    # Validate inputs
    if response is None:
        response = []
    if not isinstance(response, list):
        try:
            response = list(response)
        except TypeError:
            raise TypeError("response must be a list or iterable")
    if not isinstance(max_results, int) or max_results <= 0:
        raise ValueError("max_results must be a positive integer")

    # Generate pages
    for i in range(0, len(response), max_results):
        yield response[i:i + max_results]<|return|>

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    from collections import defaultdict
    import numbers

    # Prepare result dictionary
    result = defaultdict(float)

    # Ensure we have an iterable; if a single dict is provided, wrap it
    try:
        iterator = iter(dicts)
    except TypeError:
        # Not iterable; assume single dict
        iterator = (dicts,)

    for idx, d in enumerate(iterator):
        if not isinstance(d, dict):
            raise TypeError(f"Element {idx} is not a dict (got {type(d).__name__})")
        for key, value in d.items():
            if not isinstance(value, numbers.Number):
                raise TypeError(
                    f"Value for key '{key}' in element {idx} is not numeric (got {type(value).__name__})"
                )
            result[key] += value

    return dict(result)<|return|>

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    if not url:
        return ''

    if not url_args:
        return url

    import re
    pattern = re.compile(r'\{([^}]+)\}')

    def repl(match):
        key = match.group(1)
        if key in url_args:
            val = url_args[key]
            if val is None:
                return ''
            return str(val)
        return match.group(0)

    return pattern.sub(repl, url)<|return|>

def is_none_string(val: any) -> bool:
