def get_repo_archive(url: str, destination_path: Path) -> Path:
    """
    Given an url and a destination path, retrieve and extract .tar.gz archive
    which contains 'desc' file for each package.
    Each .tar.gz archive corresponds to an Arch Linux repo ('core', 'extra', 'community').

    Args:
        url: url of the .tar.gz archive to download
        destination_path: the path on disk where to extract archive

    Returns:
        a directory Path where the archive has been extracted to.
    """
    if not url:
        raise ValueError("url must be a non-empty string")
    if not isinstance(destination_path, Path):
        raise TypeError("destination_path must be a pathlib.Path instance")
    # Ensure destination directory exists and is empty
    try:
        if destination_path.exists():
            if any(destination_path.iterdir()):
                raise OSError(f"Destination directory {destination_path} is not empty")
        else:
            destination_path.mkdir(parents=True, exist_ok=True)
    except OSError as exc:
        raise OSError(f"Failed to prepare destination directory '{destination_path}': {exc}") from exc
    tmp_file = None
    try:
        # Download archive to a temporary file
        tmp_fd, tmp_path = os tempfile.mkstemp(suffix=".tar.gz")
        os.close(tmp_fd)
        tmp_file = Path(tmp_path)
        response = requests.get(url, stream=True, timeout=60)
        response.raise_for_status()
        with open(tmp_file, "wb") as fh:
            for chunk in response.iter_content(chunk_size=8192):
                if chunk:
                    fh.write(chunk)
        # Extract the archive
        with tarfile.open(tmp_file, "r:gz") as tar:
            tar.extractall(path=destination_path)
    except Exception as exc:
        raise RuntimeError(f"Failed to download or extract {url} to {destination_path}: {exc}") from exc
    finally:
        if tmp_file and tmp_file.exists():
            try:
                tmp_file.unlink()
            except Exception:
                pass
    return destination_path<|return|>

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        return name
    # Remove leading or trailing single or double quotes
    return re.sub(r'^[\'"]|[\'"]$', '', name)<|return|>

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import shlex
    import sys

    # Resolve platform specifier
    if platform == 'this':
        platform = 0 if sys.platform.startswith('win') else 1
    if platform == 1:
        # POSIX style splitting, use shlex for correctness
        return shlex.split(s)
    elif platform == 0:
        # Windows/CMD style splitting using a regular expression
        # Matches either a double quoted string (with support for escaped quotes)
        # or a non-whitespace unquoted token.
        token_re = r'''(?x)
            (?:
                (?P<quoted>"(?:""|[^"])*")   # quoted part
                |
                (?P<unquoted>[^ \t\r\n]+)    # unquoted part
            )
        '''
        tokens = []
        for m in re.finditer(token_re, s):
            token = m.group('quoted') or m.group('unquoted')
            if token is None:
                continue
            if token.startswith('"') and token.endswith('"'):
                # Strip outer quotes and replace double double-quotes with a single quote
                inner = token[1:-1].replace('""', '"')
                tokens.append(inner)
            else:
                tokens.append(token)
        return tokens
    else:
        raise ValueError(f"Unsupported platform specifier: {platform}")<|return|>

def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    try:
        output = subprocess.check_output(
            ['git', 'ls-files', '--others', '--ignored', '--exclude-standard'],
            stderr=subprocess.STDOUT,
            text=True
        )
    except subprocess.CalledProcessError:
        return ''
    files = [line.strip() for line in output.splitlines() if line.strip()]
    files.sort()
    return ','.join(files)<|return|>

def match(filename):
    """
    Check if the filename is a type that this module supports

    Args:
        filename: Filename to match
    Returns:
        False if not a match, True if supported
    """
    if not filename:
        return False
    supported_exts = {'.py', '.txt', '.md', '.json', '.yaml', '.yml'}
    try:
        _, ext = os.path.splitext(filename)
        return ext.lower() in supported_exts
    except Exception:
        return False<|return|>

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False
    try:
        for res in socket.getaddrinfo(host, None):
            family, _, _, _, sockaddr = res
            # IPv4
            if family == socket.AF_INET:
                ip = sockaddr[0]
                if ip.startswith("127."):
                    return True
            # IPv6
            elif family == socket.AF_INET6:
                ip = sockaddr[0]
                if ip == "::1":
                    return True
    except socket.gaierror:
        # Host could not be resolved; not local
        return False
    return False<|return|>

def _resolve_string(matcher):
    """Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised."""
    if matcher is None:
        raise ValueError('Matcher cannot be None.')

    # Extract name and optional default
    name = None
    default = None

    # Handle tuple or list
    if isinstance(matcher, (list, tuple)):
        if not matcher:
            raise ValueError('Matcher tuple/list is empty.')
        name = matcher[0]
        if len(matcher) > 1:
            default = matcher[1]
    # Handle dictionary
    elif isinstance(matcher, dict):
        if 'name' not in matcher:
            raise ValueError('Matcher dict must contain a "name" key.')
        name = matcher['name']
        default = matcher.get('default')
    # Handle object with 'name' attribute
    elif hasattr(matcher, 'name'):
        name = getattr(matcher, 'name')
        if hasattr(matcher, 'default'):
            default = getattr(matcher, 'default')
    else:
        raise TypeError('Unsupported matcher type: {}'.format(type(matcher).__name__))

    if not isinstance(name, str):
        raise TypeError('Variable name must be a string, got {}'.format(type(name).__name__))

    try:
        value = os.getenv(name)
    except Exception as exc:
        raise EnvironmentError(
            'Error retrieving environment variable "{}": {}'.format(name, exc)
        ) from exc

    if value is None:
        if default is not None:
            return default
        raise EnvironmentError(
            'Environment variable "{}" is not set and no default provided'.format(name)
        )
    return value<|return|>

def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """
    Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError:
    """
    if not isinstance(image_href, str):
        raise ValueError("image_href must be a string")

    try:
        parsed = urllib.parse.urlparse(image_href)
    except Exception as exc:
        raise ValueError(f"Invalid URL {image_href}") from exc

    scheme = parsed.scheme.lower()
    netloc = parsed.netloc
    if not scheme or not netloc:
        raise ValueError(f"URL must contain scheme and netloc: {image_href}")

    if scheme not in ("http", "https"):
        raise ValueError(f"Unsupported URL scheme: {scheme}")

    use_ssl = scheme == "https"

    # Remove trailing slash
    path = parsed.path.rstrip("/")
    if not path:
        raise ValueError(f"URL does not contain a path: {image_href}")

    # Extract last component
    name = path.split("/")[-1]
    if not name:
        raise ValueError(f"URL path does not contain an image id: {image_href}")

    # Strip extension
    if "." in name:
        image_id = name.rsplit(".", 1)[0]
    else:
        image_id = name

    if not image_id:
        raise ValueError(f"Could not extract image id from URL: {image_href}")

    return image_id, netloc, use_ssl<|return|>

def get_pattern(pattern, strip=True):
    """This method converts the given string to regex pattern"""
    # If we already have a compiled pattern, just return it
    if hasattr(re, "Pattern") and isinstance(pattern, re.Pattern):
        return pattern
    if hasattr(re, "_pattern_type") and isinstance(pattern, re._pattern_type):
        return pattern
    # If the input is a string, optionally strip whitespace and compile it
    if isinstance(pattern, str):
        if strip:
            pattern = pattern.strip()
        return re.compile(pattern)
    # Do not accept None or other types
    if pattern is None:
        raise TypeError("Pattern cannot be None")
    raise TypeError(f"Invalid pattern type: {type(pattern).__name__}")<|return|>

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Validate input types
    if not isinstance(commands, (list, tuple)):
        raise TypeError("'commands' must be a list or tuple of strings")
    if not isinstance(args, (list, tuple)):
        raise TypeError("'args' must be a list or tuple of strings")
    for c in commands:
        if not isinstance(c, str):
            raise TypeError("All elements in 'commands' must be strings")
    for a in args:
        if not isinstance(a, str):
            raise TypeError("All elements in 'args' must be strings")

    # Build the full command list
    cmd = list(commands) + list(args)

    if verbose:
        print("Running command: " + " ".join(cmd))

    # Prepare stderr handling
    stderr = subprocess.DEVNULL if hide_stderr else None

    try:
        completed = subprocess.run(
            cmd,
            cwd=cwd,
            env=env,
            capture_output=True,
            text=True,
            check=True,
            stderr=stderr
        )
        return completed.stdout
    except subprocess.CalledProcessError as exc:
        # Construct an informative error message
        msg = f"Command '{' '.join(cmd)}' failed with return code {exc.returncode}"
        if not hide_stderr and exc.stderr:
            msg += f"\nstderr:\n{exc.stderr}"
        raise RuntimeError(msg) from exc
    except Exception as exc:
        raise RuntimeError(f"Failed to run command '{' '.join(cmd)}': {exc}") from exc<|return|>

def is_ipv4(target):
    """ Test if IPv4 address or not """
    try:
        # If target is already an IPv4Address instance, just return True
        if isinstance(target, ipaddress.IPv4Address):
            return True
        # Attempt to parse the target; this will succeed for valid IPv4 strings
        ip = ipaddress.ip_address(target)
        return isinstance(ip, ipaddress.IPv4Address)
    except (ValueError, TypeError):
        # Raised when target cannot be parsed as any IP address
        return False<|return|>

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub‑class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    # Defensive guard: if graph is not provided or has no triples with the
    # specified property, return an empty set.
    if graph is None:
        return set()

    try:
        # All subjects that are linked by the predicate `prop` (i.e. children).
        children: Set["Node"] = set(graph.subjects(prop, None))
        # All objects linked by the predicate `prop` (i.e. parents).
        parents: Set["Node"] = set(graph.objects(subject=None, predicate=prop))

        # A root is a node that appears as a child but has no parents.
        candidate_roots: Set["Node"] = {node for node in children if node not in parents}

        # If a subset of roots was supplied, restrict the output to that subset.
        if roots is not None:
            # Intersect to keep only nodes that are both candidate roots and in the provided set.
            return candidate_roots & roots

        return candidate_roots

    except Exception:
        # Any exception (e.g. invalid graph, improper types) results in an empty set.
        return set()
<|return|>

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    try:
        if dumper is None:
            dumper = yaml.SafeDumper
        result = yaml.safe_dump(obj, Dumper=dumper, default_flow_style=False)
    except yaml.YAMLError as exc:
        raise ValueError(f"Failed to dump object to YAML: {exc}") from exc
    # Ensure consistent string type across Python versions
    try:
        import sys
        if sys.version_info[0] < 3 and isinstance(result, bytes):
            result = result.decode('utf-8')
    except Exception:
        pass
    return result<|return|>

def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    try:
        shape_tuple = tuple(shape)
    except Exception:
        raise TypeError("shape must be a tuple or tuple-like")
    if not isinstance(dtype, np.dtype):
        try:
            dtype = np.dtype(dtype)
        except Exception:
            raise TypeError("dtype must be a valid numpy dtype")
    try:
        return np.empty(shape_tuple, dtype=dtype)
    except Exception as exc:
        raise ValueError(f"Could not create array with shape {shape_tuple} and dtype {dtype}") from exc<|return|>

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    configs = {}
    errors = []

    def _resolve_env(value):
        """Recursively expand environment variables in strings within a configuration."""
        import os
        if isinstance(value, str):
            return os.path.expandvars(value)
        elif isinstance(value, dict):
            return {k: _resolve_env(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [_resolve_env(item) for item in value]
        return value

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as fd:
                raw = fd.read()
        except (OSError, IOError) as exc:
            errors.append(logging.makeLogRecord({
                'msg': f'Unable to read configuration file {filename!r}: {exc}',
                'level': logging.ERROR,
                'name': 'load_configurations',
            }))
            continue

        # Attempt to parse based on extension or content
        parsed = None
        ext = os.path.splitext(filename)[1].lower()
        try:
            if ext == '.json':
                parsed = json.loads(raw)
            elif ext in ('.yaml', '.yml'):
                parsed = yaml.safe_load(raw)
            elif ext == '.toml':
                parsed = toml.loads(raw)
            else:
                # Try yaml first, then json, then toml
                try:
                    parsed = yaml.safe_load(raw)
                except Exception:
                    try:
                        parsed = json.loads(raw)
                    except Exception:
                        parsed = toml.loads(raw)
        except Exception as exc:
            errors.append(logging.makeLogRecord({
                'msg': f'Error parsing configuration file {filename!r}: {exc}',
                'level': logging.ERROR,
                'name': 'load_configurations',
            }))
            continue

        if not isinstance(parsed, dict):
            errors.append(logging.makeLogRecord({
                'msg': f'Parsed configuration from {filename!r} is not a dictionary.',
                'level': logging.ERROR,
                'name': 'load_configurations',
            }))
            continue

        if resolve_env:
            parsed = _resolve_env(parsed)

        if overrides:
            if isinstance(overrides, dict):
                parsed.update(overrides)
            else:
                errors.append(logging.makeLogRecord({
                    'msg': f'Overrides provided for {filename!r} are not a dictionary.',
                    'level': logging.ERROR,
                    'name': 'load_configurations',
                }))

        configs[filename] = parsed

    return configs, errors<|return|>

def force_string(obj):
    """
    This function returns the bytes object corresponding to ``obj`` in case it is a string using UTF-8. 
    """
    if isinstance(obj, str):
        try:
            return obj.encode('utf-8')
        except Exception as e:
            raise ValueError(f"Failed to encode string to UTF-8: {e}") from e
    else:
        return obj<|return|>

@classmethod
def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    if values is None:
        raise ValueError("values must not be None")
    # Ensure we have an iterable
    try:
        iterator = iter(values)
    except TypeError:
        raise TypeError("values must be an iterable of strings")
    # Validate and collect the raw string values
    cleaned = []
    for idx, val in enumerate(iterator):
        if not isinstance(val, str):
            raise TypeError(f"item {idx} in values is not a string")
        cleaned.append(val)
    # Instantiate a Bookmarks object (assumes __init__ accepts a list of values)
    return cls(cleaned)<|return|>

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # Validate get_coordinate
    if get_coordinate not in ("left", "right", "middle"):
        raise ValueError(f"Invalid get_coordinate: {get_coordinate!r}")

    # Determine scale of resulting graph
    if scale is True:
        scale = getattr(hist, "scale", None)
    # else keep provided scale (could be None)

    # Determine how many values each point will hold
    if make_value is None:
        # single value from content
        val_func = lambda content: content
    else:
        val_func = make_value

    # Prepare output container
    points = []

    # Determine number of fields expected from val_func
    # If make_value returns a tuple/list, infer field count
    # Otherwise assume single value
    sample_val = None
    # Try to infer by applying val_func to a sample bin content if exists
    # We assume hist.bins or hist.data is accessible
    try:
        bins = getattr(hist, "bins", None)
        if bins is None:
            bins = getattr(hist, "data", [])
        if isinstance(bins, dict):
            # Some histograms store bins as dict with keys as bin edges or tuple indexes
            bin_items = sorted(bins.items())
            sample_bin = bin_items[0] if bin_items else None
        else:
            # Iterable of bin objects or values
            sample_bin = bins[0] if len(bins) > 0 else None
    except Exception:
        sample_bin = None

    if sample_bin is not None:
        # Determine content of bin
        # Try to get the bin content
        try:
            content = getattr(sample_bin, "content", None)
            if content is None:
                # If bin itself is content
                content = sample_bin
        except Exception:
            content = sample_bin
        try:
            sample_val = val_func(content)
        except Exception:
            sample_val = None

    if sample_val is None:
        # default to single field
        field_name_count = 1
    elif isinstance(sample_val, (tuple, list)):
        field_name_count = len(sample_val)
    else:
        field_name_count = 1

    # Validate field_names length
    if len(field_names) != field_name_count:
        raise ValueError(
            f"field_names length {len(field_names)} does not match the "
            f"expected number of values {field_name_count}"
        )

    # Helper to get coordinate
    def _get_coord(bin_obj):
        # Try left, right, center attributes
        coord = None
        try:
            coord = getattr(bin_obj, get_coordinate)
        except Exception:
            pass
        if coord is None:
            # try left or right attributes
            try:
                left = getattr(bin_obj, "left", None)
                right = getattr(bin_obj, "right", None)
                center = getattr(bin_obj, "center", None)
                if get_coordinate == "left" and left is not None:
                    coord = left
                elif get_coordinate == "right" and right is not None:
                    coord = right
                elif get_coordinate == "middle" and center is not None:
                    coord = center
                elif get_coordinate == "middle" and left is not None and right is not None:
                    coord = 0.5 * (left + right)
            except Exception:
                pass
        if coord is None:
            # assume bin_obj itself is a numeric coordinate
            coord = bin_obj
        return coord

    # Iterate over bins
    for bin_obj in bins:
        # Get coordinate
        try:
            coord = _get_coord(bin_obj)
        except Exception:
            coord = None

        # Get content value
        try:
            content = getattr(bin_obj, "content", None)
            if content is None:
                # fallback: bin object holds content directly
                content = bin_obj
        except Exception:
            content = bin_obj

        # Compute point values
        try:
            point_vals = val_func(content)
        except Exception as exc:
            raise RuntimeError(f"make_value function failed on content {content}") from exc

        # Pack into dict
        if isinstance(point_vals, (tuple, list)):
            point_dict = {name: val for name, val in zip(field_names, point_vals)}
        else:
            # single value
            point_dict = {field_names[0]: point_vals}

        # Add coordinate field
        point_dict[field_names[0]] = coord if coord is not None else point_dict.get(field_names[0])

        points.append(point_dict)

    # Build graph object as dict
    graph = {
        "data": points,
        "scale": scale,
        "field_names": field_names,
    }
    return graph<|return|>

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Validation of arguments
    if iface is None:
        raise ValueError('iface cannot be None')
    if candidate is None:
        raise ValueError('candidate cannot be None')

    # Determine if iface is a class/type or a collection of required attribute names
    iface_is_cls = isinstance(iface, type)
    iface_is_iter = hasattr(iface, '__iter__') and not iface_is_cls and not isinstance(iface, (str, bytes))

    # Helper to perform the actual check
    def _check() -> bool:
        # Determine the actual type of the candidate: if instance, get its class
        target_cls = candidate if isinstance(candidate, type) else type(candidate)

        if iface_is_cls:
            try:
                return issubclass(target_cls, iface)
            except TypeError:
                # target_cls is not a class (e.g. a function or value)
                return False

        if iface_is_iter:
            # The interface is specified as an iterable of attribute names (methods, properties, etc.)
            for attr in iface:
                if not hasattr(target_cls, attr):
                    return False
            return True

        # Unsupported iface type
        raise TypeError('iface must be a class or an iterable of attribute names')

    # Perform the check and handle tentative mode
    result = _check()
    if tentative:
        return result

    if not result:
        raise TypeError(f'Candidate {candidate!r} does not satisfy the interface {iface!r}')
    # Successful verification: no return value needed (None)                                <|return|>

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    # Attempt to delegate to the underlying mapping implementation
    # (e.g., a dict or a superclass that implements pop).
    try:
        # super() is used in case this method overrides a built-in pop.
        return super().pop(key)
    except KeyError:
        # If the key was not found, decide whether to return the default
        if default is __marker:
            raise
        return default
    except AttributeError:
        # Fallback: use the instance's own dictionary if super() is unavailable.
        if default is __marker and key not in self.__dict__:
            raise KeyError(key)
        return self.__dict__.pop(key, default)<|return|>

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    # Verify that the container has any items
    try:
        # If there is a frequency table we use it to find the least used key
        lf_key = None
        if hasattr(self, "_freq") and isinstance(self._freq, dict):
            # Find key with minimal frequency; break ties by key order
            try:
                lf_key = min(self._freq.items(), key=lambda kv: kv[1])[0]
                # In case the frequency dict contains keys no longer in data, fall back
                if lf_key not in self._data:
                    lf_key = None
            except ValueError:
                lf_key = None
        # If we couldn't determine via frequency (or no freq table), fallback to first key
        if lf_key is None:
            if not self._data:
                raise KeyError("LFU cache is empty")
            lf_key = next(iter(self._data))
    except Exception:
        # any unexpected issue: surface clear error
        raise KeyError("Unable to determine least frequently used key")
    # Remove and return the pair
    try:
        value = self._data.pop(lf_key)
        # Clean up frequency table entry if present
        if hasattr(self, "_freq") and isinstance(self._freq, dict):
            self._freq.pop(lf_key, None)
        return (lf_key, value)
    except KeyError:
        # In the unlikely event that the key disappears between lookup and pop
        raise KeyError(f"Key {lf_key!r} not found during popitem")<|return|>

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    # The LRU cache is typically backed by an OrderedDict named `_cache`.
    # This method removes the oldest entry (least recently used).
    if not hasattr(self, "_cache"):
        raise AttributeError("LRUCache object missing internal '_cache' attribute")
    try:
        return self._cache.popitem(last=False)
    except KeyError:
        raise KeyError("LRU cache is empty") from None<|return|>

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    try:
        return dict.popitem(self)
    except KeyError:
        raise KeyError('popitem(): dictionary is empty')<|return|>

