def set_cut_chars(self, before: bytes, after: bytes) -> None:
    """Set the bytes used to delimit slice points.

    Args:
        before: Split file before these delimiters.
        after: Split file after these delimiters.
    """
    # Allow None to be treated as an empty delimiter
    if before is None:
        before = b''
    if after is None:
        after = b''
    # Ensure the inputs are convertible to immutable bytes objects
    try:
        before = bytes(before)
    except Exception as exc:
        raise TypeError("`before` must be bytes-like") from exc
    try:
        after = bytes(after)
    except Exception as exc:
        raise TypeError("`after` must be bytes-like") from exc
    # Store the delimiters on the instance
    self._cut_before = before
    self._cut_after = after<|return|>

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Private encrypted JSON payload
    try:
        data = json.loads(decode_if_bytes(request.body))
        if "encrypted_magic_envelope" in data:
            return True
    except Exception:
        pass
    # Public XML payload
    try:
        xml = etree.fromstring(encode_if_text(request.body))
        if xml.tag == MAGIC_ENV_TAG:
            return True
    except Exception:
        pass
    return False<|return|>

def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    if not isinstance(dt, datetime.datetime):
        raise TypeError("dt must be a datetime.datetime instance")
    try:
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        else:
            dt = dt.astimezone(datetime.timezone.utc)
        # Produce ISO 8601 with milliseconds, trailing 'Z'
        iso_str = dt.strftime("%Y-%m-%dT%H:%M:%S.%fZ")
        return iso_str[:-3]  # keep only three fractional digits
    except Exception as exc:
        raise ValueError("Failed to format datetime") from exc<|return|>

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    if not isinstance(text, str):
        raise ValueError("text must be a string")
    # Regular expression to match URLs beginning with http://, https://, or ftp://
    url_pattern = re.compile(r'\b(?:https?://|ftp://)[^\s<>\"]+')

    def replace(match):
        url = match.group(0)
        # Wrap URL in an <a> tag with target="_blank" for safe navigation
        return f'<a target="_blank" href="{url}">{url}</a>'

    try:
        # Substitutes all discovered URLs with linkified versions
        return url_pattern.sub(replace, text)
    except re.error:
        # In case regex compilation or substitution fails, return original text
        return text<|return|>

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    if not isinstance(url, str) or not url:
        return None
    try:
        parsed = urllib.parse.urlparse(url)
        if parsed.scheme not in ("http", "https"):
            return None

        req = urllib.request.Request(url, method="HEAD", headers={"User-Agent": "Python-urllib/3"})
        try:
            with urllib.request.urlopen(req, timeout=10) as resp:
                status = getattr(resp, "status", getattr(resp, "getcode", lambda: None)())
                if status is None or status >= 400:
                    return None
                return resp.headers.get("content-type")
        except urllib.error.HTTPError as e:
            # HTTPError provides a response object with headers
            status = getattr(e, "code", None)
            if status is None or status >= 400:
                return None
            return e.headers.get("content-type")
        except urllib.error.URLError:
            return None
    except Exception:
        return None<|return|>

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    import re
    if not isinstance(tag, str):
        raise TypeError("'tag' must be a string")
    tag = tag.strip()
    if not tag:
        return False
    pattern = r'^[A-Za-z0-9_-]+$'
    return re.match(pattern, tag) is not None<|return|>

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        return {}
    # node may be an ElementTree; use its root if so
    if hasattr(node, 'getroot'):
        node = node.getroot()
    result = {}
    try:
        for child in node:
            tag = child.tag
            if tag in result:
                existing = result[tag]
                if isinstance(existing, list):
                    existing.append(child)
                else:
                    result[tag] = [existing, child]
            else:
                result[tag] = child
    except Exception:
        # If node is not iterable or has no children, return empty dict
        pass
    return result<|return|>

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Basic validation of the base URL
    if not url or not isinstance(url, str):
        raise ValueError("The 'url' argument must be a non-empty string.")
    # Normalize the base URL and construct the full href
    base_clean = url.rstrip('/')
    # Use provided document path, or fall back to the standard NodeInfo 1.0 path
    if document_path:
        # Ensure the document path starts with a slash to avoid malformed URLs
        doc_path = document_path if document_path.startswith('/') else '/' + document_path
        href = base_clean + doc_path
    else:
        href = f"{base_clean}/.well-known/nodeinfo/1"
    # Return the well-known document structure
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/1.0",
                "href": href
            }
        ]
    }<|return|>

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    # Helper to create link dicts with rel and href
    def _add_link(links, rel, href):
        if href and rel:
            links.append({"rel": rel, "href": href})

    result: Dict = {}
    links: list = []

    # Try JSON first
    try:
        data = json.loads(document)
    except Exception:
        data = None

    if data is not None:
        try:
            subject = data.get("subject") or data.get("sub")
        except Exception:
            subject = None
        result["subject"] = subject
        for l in data.get("links", []):
            rel = l.get("rel")
            href = l.get("href")
            _add_link(links, rel, href)
        result["links"] = links
        # Attempt to pull hcard_url for convenience
        for l in links:
            if l["rel"] in ("hcard", "http://microformats.org/profile/hcard"):
                result["hcard_url"] = l["href"]
                break
        return result

    # Fallback to XRD (XML)
    try:
        # Parse XML, respecting encoding
        parser = ET.XMLParser(encoding="utf-8")
        root: ET.Element = ET.fromstring(document.encode("utf-8"), parser=parser)

        ns = {"xrd": "http://xri.net/xrd"}
        subject = root.findtext("xrd:Subject", namespaces=ns)
        result["subject"] = subject

        for link_el in root.findall("xrd:Link", namespaces=ns):
            rel = link_el.get("rel")
            href_el = link_el.find("xrd:Href", namespaces=ns)
            href = href_el.text if href_el is not None else None
            _add_link(links, rel, href)

        result["links"] = links
        # Attempt to pull hcard_url for convenience
        for l in links:
            if l["rel"] in ("hcard", "http://microformats.org/profile/hcard"):
                result["hcard_url"] = l["href"]
                break
        return result
    except Exception:
        # If parsing fails, return empty dict
        return {}
<|return|>

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        host = handle.split("@")[1]
    except (AttributeError, IndexError):
        return None

    try:
        from urllib.parse import quote
    except ImportError:
        # Fallback for Python 2
        from urllib import quote  # type: ignore

    url = f"https://{host}/.well-known/webfinger?resource=acct:{quote(handle)}"

    try:
        with closing(urllib2.urlopen(url, timeout=10)) as page:
            if page.getcode() != 200:
                return None
            content = page.read()
            if isinstance(content, bytes):
                content = content.decode("utf-8", errors="ignore")
            return content
    except Exception:
        return None<|return|>

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        host = handle.split("@")[1]
    except AttributeError:
        logger.warning("retrieve_and_parse_diaspora_webfinger: invalid handle given: %s", handle)
        return None
    document, code, exception = fetch_document(
        host=host, path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if document:
        return parse_diaspora_webfinger(document)
    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None
    url = hostmeta.find_link(rels="lrdd").template.replace("{uri}", quote(handle))
    document, code, exception = fetch_document(url)
    if exception:
        return None
    return parse_diaspora_webfinger(document)<|return|>

