@classmethod
    def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
         is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        if spec_content is None:
            raise IRValidatorException("spec_content must be provided")

        try:
            data = yaml.safe_load(spec_content)
        except Exception as exc:
            raise IRValidatorException(f"Failed to parse YAML content: {exc}") from exc

        if not isinstance(data, dict):
            raise IRValidatorException("Parsed content is not a dictionary")

        required_fields = ['name', 'type', 'version']
        missing = [field for field in required_fields if field not in data]
        if missing:
            raise IRValidatorException(
                f"Missing required field(s) in spec: {', '.join(missing)}"
            )

        return data<|return|>

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    # Helper to fetch value from spec if possible
    def spec_get(name):
        if self.spec is None:
            return None
        try:
            if hasattr(self.spec, "get"):
                return self.spec.get(name)
            if isinstance(self.spec, dict):
                return self.spec.get(name)
        except Exception:
            return None
        return None

    for arg in getattr(self, "args", []):
        if not isinstance(arg, _BaseOpt):
            continue

        # Try to get value from spec first
        val = spec_get(arg.name)

        # If spec does not provide a value, fall back to argument default
        if val is None and not isinstance(arg.default, NoDefault):
            val = arg.default

        # For dict options, recurse into the nested scheme if needed
        if isinstance(arg, DictOption):
            if isinstance(val, dict):
                # Use the spec's dict as the source for nested defaults
                try:
                    nested_defaults = arg.scheme.get_spec_defaults()
                except Exception:
                    nested_defaults = {}
                if nested_defaults:
                    defaults[arg.name] = nested_defaults
                else:
                    defaults[arg.name] = val
            elif val is None:
                # No spec-provided dict, use defaults from nested scheme
                try:
                    nested_defaults = arg.scheme.get_spec_defaults()
                except Exception:
                    nested_defaults = {}
                if nested_defaults:
                    defaults[arg.name] = nested_defaults
        else:
            if val is not None:
                defaults[arg.name] = val
    return defaults<|return|>

