def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    if not isinstance(cli_args, dict):
        raise TypeError(f"cli_args must be a dict, got {type(cli_args).__name__}")
    if not isinstance(answer_file_args, dict):
        raise TypeError(f"answer_file_args must be a dict, got {type(answer_file_args).__name__}")

    # Retrieve the deprecated argument map, if defined; otherwise use an empty dict.
    deprecated_map = getattr(self, "deprecated_args", {})
    if not isinstance(deprecated_map, dict):
        raise TypeError(
            f"deprecated_args attribute must be a dict if defined, got {type(deprecated_map).__name__}"
        )

    # Collect deprecation messages for CLI and answer-file arguments.
    messages = []
    for source_name, args in (("CLI", cli_args), ("Answer file", answer_file_args)):
        for arg_name in args:
            if arg_name in deprecated_map:
                new_arg = deprecated_map[arg_name]
                messages.append(
                    f"{source_name} argument '{arg_name}' is deprecated; use '{new_arg}' instead."
                )

    # Emit warnings for any deprecated arguments found.
    if messages:
        # Import warnings lazily to avoid unnecessary import if not used.
        import warnings
        for msg in messages:
            warnings.warn(msg, DeprecationWarning, stacklevel=2)'''<|return|>

def get_parser_option_specs(self, command_name):
    """
    Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    if not isinstance(command_name, str) or not command_name.strip():
        raise ValueError("command_name must be a non-empty string")
    command_name = command_name.strip()
    parser_specs = getattr(self, "_command_parser_specs", {})
    # Attempt direct lookup
    spec = parser_specs.get(command_name)
    if spec is None:
        # Case‑insensitive lookup
        for key, value in parser_specs.items():
            if key.lower() == command_name.lower():
                spec = value
                break
    if spec is None:
        available = list(parser_specs.keys())
        raise KeyError(f"Command '{command_name}' not found. Available commands: {available}")
    # Extract options
    if hasattr(spec, "options"):
        return spec.options
    if isinstance(spec, dict) and "options" in spec:
        return spec["options"]
    if isinstance(spec, list):
        return spec
    # If option extraction fails, return an empty list
    return []<|return|>

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    if not isinstance(command_name, str) or not isinstance(argument_name, str):
        raise TypeError("command_name and argument_name must be strings")
    options = getattr(self, "_option_specs", {})
    if command_name not in options:
        raise KeyError(f"Command '{command_name}' not found in option specifications")
    command_options = options[command_name]
    if argument_name not in command_options:
        raise KeyError(f"Argument '{argument_name}' not found for command '{command_name}'")
    return command_options[argument_name]<|return|>

def get_silent_args(self, args):
        """
        Return list of silenced argument names from args.

        :param args: list of strings (command line args)
        :return: list of argument names (without preceding dashes) that are considered silent.
        """
        if not isinstance(args, (list, tuple)):
            raise TypeError("args must be a list or tuple of strings")
        # A set of silent option names (without dashes). If the attribute is missing,
        # assume no silent options.
        silent_names = getattr(self, "_silent_argument_names", set())
        silent_args = []
        for arg in args:
            if not isinstance(arg, str):
                continue
            if arg.startswith("-"):
                name = arg.lstrip("-")
                if name in silent_names:
                    silent_args.append(name)
        return silent_args<|return|>

def validate_requires_args(self, args):
    """
    Check if all the required arguments have been provided.
    """
    # Determine the list of required arguments.  If the object does not
    # provide ``self.required_args`` we treat the method as a no‑op.
    required = getattr(self, 'required_args', [])
    if not required:
        return True

    # Ensure ``args`` is a mapping.
    if not isinstance(args, dict):
        raise TypeError('args must be a mapping of argument names to values')

    missing = []
    for name in required:
        if name not in args:
            missing.append(name)
        elif args[name] is None:
            missing.append(name)

    if missing:
        miss_str = ', '.join(missing)
        raise ValueError(f'Missing required argument(s): {miss_str}')

    return True<|return|>

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    result = []
    for opt in options_spec:
        # obtain option name
        if isinstance(opt, dict):
            name = opt.get('name')
            required_when = opt.get('required_when')
        else:
            name = getattr(opt, 'name', None)
            required_when = getattr(opt, 'required_when', None)

        if name is None or required_when is None:
            continue

        matched = False

        # Evaluate specified condition
        try:
            if callable(required_when):
                matched = bool(required_when(command_name, args))
            elif isinstance(required_when, (list, tuple, set)):
                matched = command_name in required_when
            else:
                matched = command_name == required_when
        except Exception:
            # ignore failure to evaluate condition
            matched = False

        if matched:
            result.append(name)

    return result
