def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Retrieve argument specifications from the parsed YAML configuration.
    arg_specs = self.parsed_yaml.get('args', {})

    # Helper to look up the maximum length for a given argument name.
    def _max_length_for(name):
        max_len = None
        if isinstance(arg_specs, dict):
            spec = arg_specs.get(name)
            if isinstance(spec, dict):
                max_len = spec.get('max_length')
        else:  # Expect a list of one‑item dicts.
            for spec_dict in arg_specs:
                if name in spec_dict:
                    spec = spec_dict[name]
                    if isinstance(spec, dict):
                        max_len = spec.get('max_length')
                    break
        return max_len

    for arg_name, arg_value in args.items():
        max_len = _max_length_for(arg_name)
        if max_len is None:
            continue

        # Ensure max_len is an integer.
        if not isinstance(max_len, int):
            raise TypeError(
                f"max_length for argument '{arg_name}' must be an int (got {type(max_len).__name__})")

        if max_len < 0:
            raise ValueError(
                f"max_length for argument '{arg_name}' must be non‑negative (got {max_len})")

        # Convert the value to a string and check its length.
        try:
            value_str = str(arg_value)
        except Exception:  # pragma: no cover
            # If conversion fails, skip length check.
            continue

        if len(value_str) > max_len:
            raise ValueError(
                f"Argument '{arg_name}' exceeds maximum length {max_len}: '{value_str}'")
