def validate_choices_args(self, args):
    """
    Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Build a mapping of argument names to their valid choices if not already present.
    if not hasattr(self, "_choice_map") or not isinstance(self._choice_map, dict):
        self._choice_map = {}
        arg_def = self.parsed_yaml.get("args", {})
        if isinstance(arg_def, dict):
            for arg_name, attrs in arg_def.items():
                if isinstance(attrs, dict) and "choices" in attrs:
                    self._choice_map[arg_name] = attrs["choices"]
        else:
            for item in arg_def:
                if isinstance(item, dict):
                    arg_name, attrs = next(iter(item.items()))
                    if isinstance(attrs, dict) and "choices" in attrs:
                        self._choice_map[arg_name] = attrs["choices"]

    # Validate each argument that has defined choices.
    for arg_name, value in args.items():
        if arg_name in self._choice_map:
            allowed = self._choice_map[arg_name]
            if value not in allowed:
                raise ValueError(
                    f"Invalid value for argument '{arg_name}': "
                    f"'{value}'. Allowed values are: {allowed}"
                )
    return None<|return|>

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    :returns: dict - The merged dictionary
    """
    if vars_dict is None:
        raise ValueError("vars_dict must be a dictionary")
    if not isinstance(vars_dict, dict):
        raise TypeError(f"vars_dict must be dict, got {type(vars_dict).__name__}")

    merged = dict(vars_dict)

    if not extra_vars:
        return merged

    if not isinstance(extra_vars, (list, tuple)):
        raise TypeError("extra_vars must be a list or tuple")

    for item in extra_vars:
        if isinstance(item, dict):
            merged.update(item)
        elif isinstance(item, (list, tuple)) and len(item) == 2:
            key, value = item
            merged[key] = value
        # Items that are not dicts or 2-tuples are ignored to avoid errors

    return merged<|return|>

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict param.
    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of arguments.
    """
    # A mapping of parser names to a dict that assigns each arg key a target type.
    # This mapping is expected to be defined on the instance, e.g.
    # self.parser_type_map = {
    #     'main': {'threads': 'int', 'verbose': 'bool', 'filenames': 'list'},
    #     ...
    # }
    parser_type_map = getattr(self, 'parser_type_map', {})
    type_map = parser_type_map.get(parser_name, {})

    for key, target_type in type_map.items():
        if key not in values_dict:
            continue
        val = values_dict[key]
        # Skip conversion if already of correct type
        try:
            if target_type == 'int':
                if not isinstance(val, int):
                    values_dict[key] = int(val)
            elif target_type == 'float':
                if not isinstance(val, float):
                    values_dict[key] = float(val)
            elif target_type == 'bool':
                if not isinstance(val, bool):
                    # Convert common string representations to bool
                    if isinstance(val, str):
                        values_dict[key] = val.lower() in ('1', 'true', 'yes', 'y', 'on')
                    else:
                        values_dict[key] = bool(val)
            elif target_type == 'list':
                if not isinstance(val, list):
                    if isinstance(val, str):
                        # split on commas, strip whitespace, ignore empty elements
                        values_dict[key] = [v.strip() for v in val.split(',') if v.strip()]
                    else:
                        values_dict[key] = list(val)
            else:
                # Unknown target type: leave value unchanged
                pass
        except Exception:
            # If conversion fails, leave the original value untouched
            pass

    # Return the modified dictionary for convenience
    return values_dict<|return|>

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import json
    import os
    from pathlib import Path

    def _flatten(src, parent_key="", sep="."):
        flat = {}
        for key, value in src.items():
            new_key = f"{parent_key}{sep}{key}" if parent_key else key
            if isinstance(value, dict):
                flat.update(_flatten(value, new_key, sep=sep))
            else:
                flat[new_key] = value
        return flat

    if not plugin_dir:
        return {}

    plugin_path = Path(plugin_dir)
    if not plugin_path.is_dir():
        return {}

    spec_files = [
        ("plugin.json", "json"),
        ("plugin.yml", "yaml"),
        ("plugin.yaml", "yaml"),
    ]

    spec_dict = None

    for filename, fmt in spec_files:
        candidate = plugin_path / filename
        if candidate.is_file():
            try:
                with candidate.open("r", encoding="utf-8") as f:
                    if fmt == "json":
                        spec_dict = json.load(f)
                    else:  # yaml
                        try:
                            import yaml
                        except ImportError:
                            # YAML loader not available; skip this file
                            continue
                        spec_dict = yaml.safe_load(f)
                if isinstance(spec_dict, dict):
                    break
            except Exception:
                # Any error reading/decoding the file is ignored; try next candidate
                pass

    if not isinstance(spec_dict, dict):
        return {}

    return _flatten(spec_dict)
